As the **Specialized Backend Developer**, I have engineered the **Google Workspace Integration Layer**. This layer acts as the critical bridge between the Supabase/Next.js infrastructure and Apex Roofing’s legacy spreadsheet-based operations.

This implementation includes the OAuth2 credential management system, a centralized Google Service Layer for Sheets and Drive, and the necessary Supabase Edge Function logic to handle background synchronization.

---

### 1. Google Cloud Console Configuration (Pre-requisites)
To enable this layer, the following must be configured in the [Google Cloud Console](https://console.cloud.google.com/):
1.  **Enable APIs:** Google Drive API, Google Sheets API.
2.  **OAuth Consent Screen:** Set to "Internal" (since this is for Apex Roofing staff). Add scopes: `.../auth/drive.file`, `.../auth/spreadsheets`.
3.  **Credentials:** Create "OAuth 2.0 Client IDs" (Web Application).
4.  **Redirect URI:** `https://<PROJECT_ID>.supabase.co/functions/v1/google-auth-callback`

---

### 2. Token Storage Schema (Supabase)
We need a secure place to store encrypted OAuth tokens. Run this in your Supabase SQL Editor:

```sql
-- Store Google OAuth Credentials per Admin/Organization
CREATE TABLE IF NOT EXISTS google_integrations (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
    access_token TEXT NOT NULL,
    refresh_token TEXT NOT NULL,
    expiry_date BIGINT NOT NULL,
    spreadsheet_id TEXT, -- The "Master Spreadsheet" ID
    root_drive_folder_id TEXT, -- Root folder for Apex Photos
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Enable RLS so only admins can manage integrations
ALTER TABLE google_integrations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins can manage their own integration" ON google_integrations
    FOR ALL TO authenticated USING (auth.jwt() ->> 'role' = 'admin');
```

---

### 3. API Service Layer: `GoogleWorkspaceService.ts`
This service encapsulates all logic for interacting with Sheets and Drive. It handles automatic token refreshing.

```typescript
// services/GoogleWorkspaceService.ts
import { google } from 'googleapis';
import { createClient } from '@supabase/supabase-js';

export class GoogleWorkspaceService {
  private auth;
  private supabase;

  constructor(accessToken: string, refreshToken: string, expiry: number) {
    this.auth = new google.auth.OAuth2(
      process.env.GOOGLE_CLIENT_ID,
      process.env.GOOGLE_CLIENT_SECRET,
      process.env.GOOGLE_REDIRECT_URI
    );

    this.auth.setCredentials({
      access_token: accessToken,
      refresh_token: refreshToken,
      expiry_date: expiry,
    });

    this.supabase = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!
    );
  }

  /**
   * Refreshes the token if expired and updates Supabase
   */
  async refreshCredentials(userId: string) {
    this.auth.on('tokens', async (tokens) => {
      if (tokens.refresh_token) {
        await this.supabase
          .from('google_integrations')
          .update({ 
            access_token: tokens.access_token,
            refresh_token: tokens.refresh_token,
            expiry_date: tokens.expiry_date 
          })
          .eq('user_id', userId);
      } else {
        await this.supabase
          .from('google_integrations')
          .update({ 
            access_token: tokens.access_token,
            expiry_date: tokens.expiry_date 
          })
          .eq('user_id', userId);
      }
    });
  }

  /**
   * LEADS INTEGRATION: Appends a new lead to the Master Spreadsheet
   */
  async appendLeadToSheet(spreadsheetId: string, leadData: any) {
    const sheets = google.sheets({ version: 'v4', auth: this.auth });
    const range = 'Leads!A:G'; // Assumes a 'Leads' tab exists

    const values = [[
      new Date().toISOString(),
      leadData.customer_name,
      leadData.phone,
      leadData.source,
      leadData.ai_metadata?.urgency_score || 'N/A',
      leadData.ai_metadata?.summary || '',
      'New'
    ]];

    return await sheets.spreadsheets.values.append({
      spreadsheetId,
      range,
      valueInputOption: 'USER_ENTERED',
      requestBody: { values },
    });
  }

  /**
   * PHOTO INTEGRATION: Creates folder structure and uploads categorized photo
   */
  async uploadPhotoToDrive(parentFolderId: string, jobName: string, category: string, fileName: string, fileStream: any) {
    const drive = google.drive({ version: 'v3', auth: this.auth });

    // 1. Ensure Job Folder exists
    const jobFolder = await this.getOrCreateFolder(drive, jobName, parentFolderId);

    // 2. Ensure Category Folder exists (e.g., 'Front Elevation')
    const categoryFolder = await this.getOrCreateFolder(drive, category, jobFolder);

    // 3. Upload File
    return await drive.files.create({
      requestBody: {
        name: fileName,
        parents: [categoryFolder],
      },
      media: {
        mimeType: 'image/jpeg',
        body: fileStream,
      },
      fields: 'id, webViewLink',
    });
  }

  private async getOrCreateFolder(drive: any, folderName: string, parentId?: string) {
    const query = `name = '${folderName}' and mimeType = 'application/vnd.google-apps.folder' ${parentId ? `and '${parentId}' in parents` : ''} and trashed = false`;
    const res = await drive.files.list({ q: query, fields: 'files(id)' });

    if (res.data.files.length > 0) {
      return res.data.files[0].id;
    }

    const folder = await drive.files.create({
      requestBody: {
        name: folderName,
        mimeType: 'application/vnd.google-apps.folder',
        parents: parentId ? [parentId] : [],
      },
      fields: 'id',
    });
    return folder.data.id;
  }
}
```

