### 4. OAuth2 Flow Implementation (Next.js API Routes)
This handles the initial connection of the Apex Roofing Admin's Google account.

```typescript
// app/api/auth/google/route.ts
import { google } from 'googleapis';
import { createRouteHandlerClient } from '@supabase/auth-helpers-nextjs';
import { cookies } from 'next/headers';

const oauth2Client = new google.auth.OAuth2(
  process.env.GOOGLE_CLIENT_ID,
  process.env.GOOGLE_CLIENT_SECRET,
  process.env.GOOGLE_REDIRECT_URI
);

export async function GET() {
  const scopes = [
    'https://www.googleapis.com/auth/drive.file',
    'https://www.googleapis.com/auth/spreadsheets'
  ];

  const url = oauth2Client.generateAuthUrl({
    access_type: 'offline', // Critical for getting the refresh_token
    scope: scopes,
    prompt: 'consent'
  });

  return Response.redirect(url);
}

// app/api/auth/google/callback/route.ts
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const code = searchParams.get('code');
  const supabase = createRouteHandlerClient({ cookies });
  const { data: { user } } = await supabase.auth.getUser();

  const { tokens } = await oauth2Client.getToken(code!);

  // Store tokens in Supabase
  await supabase.from('google_integrations').upsert({
    user_id: user?.id,
    access_token: tokens.access_token,
    refresh_token: tokens.refresh_token,
    expiry_date: tokens.expiry_date,
  });

  return Response.redirect(`${process.env.NEXT_PUBLIC_SITE_URL}/admin/settings?status=success`);
}
```

