### 2. Service Implementation: `GeminiService.ts`

This service uses the `@google/generative-ai` SDK and is optimized for the Next.js environment.

```typescript
// services/GeminiService.ts
import { GoogleGenerativeAI, SchemaType } from "@google/generative-ai";

const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY!);

export class GeminiService {
  /**
   * 1. VISION: Categorizes roofing photos for insurance documentation
   */
  static async classifyRoofingImage(imageBuffer: Buffer, mimeType: string) {
    const model = genAI.getGenerativeModel({ 
      model: "gemini-1.5-flash",
      generationConfig: { responseMimeType: "application/json" }
    });

    const prompt = `Analyze this roofing photo. Categorize it into one of: Front Elevation, Rear Elevation, Left Elevation, Right Elevation, Hail Damage, Wind Damage, or Shingle Detail. Return JSON with 'category', 'damage_detected' (boolean), and 'technical_summary'.`;

    const result = await model.generateContent([
      prompt,
      { inlineData: { data: imageBuffer.toString("base64"), mimeType } }
    ]);

    return JSON.parse(result.response.text());
  }

  /**
   * 2. NLP: Parses SMS leads into structured data for Google Sheets
   */
  static async parseLeadConversation(conversationHistory: string) {
    const model = genAI.getGenerativeModel({ 
      model: "gemini-1.5-flash",
      generationConfig: { 
        responseMimeType: "application/json",
        // Enforce schema for reliability
        responseSchema: {
          type: SchemaType.OBJECT,
          properties: {
            customer_name: { type: SchemaType.STRING },
            urgency: { type: SchemaType.STRING },
            damage_type: { type: SchemaType.STRING },
            summary: { type: SchemaType.STRING }
          }
        }
      }
    });

    const prompt = `Extract lead details from this SMS history: ${conversationHistory}`;
    const result = await model.generateContent(prompt);
    return JSON.parse(result.response.text());
  }

  /**
   * 3. GENERATIVE: Creates personalized re-engagement messages
   */
  static async generateEstimateFollowUp(customerData: { name: string, damage: string, amount: number }) {
    const model = genAI.getGenerativeModel({ model: "gemini-1.5-pro" });

    const prompt = `Draft a short, professional SMS to ${customerData.name} regarding their ${customerData.damage} estimate of $${customerData.amount}. It has been 30 days. Ask if they have questions about the insurance claim process. Keep it under 160 characters.`;

    const result = await model.generateContent(prompt);
    return result.response.text();
  }

  /**
   * 4. DATA CLEANING: Deduplicates and standardizes spreadsheet rows
   */
  static async cleanSpreadsheetData(rows: any[]) {
    const model = genAI.getGenerativeModel({ 
      model: "gemini-1.5-pro",
      generationConfig: { responseMimeType: "application/json" }
    });

    const prompt = `Review these roofing job records. Standardize address formats, fix typos in names, and identify potential duplicates. Return a cleaned JSON array. Data: ${JSON.stringify(rows)}`;

    const result = await model.generateContent(prompt);
    return JSON.parse(result.response.text());
  }
}
```

