### 3. Functional Module (Backend Logic)

#### A. `photo-actions.ts` (Next.js Server Action)
This is the orchestrator that bridges Supabase, Gemini, and Google Drive.

```typescript
// app/actions/photo-actions.ts
'use server';

import { createServerActionClient } from '@supabase/auth-helpers-nextjs';
import { cookies } from 'next/headers';
import { GeminiService } from '@/services/GeminiService';
import { GoogleWorkspaceService } from '@/services/GoogleWorkspaceService';

export async function uploadAndCategorizePhoto(formData: FormData) {
  const supabase = createServerActionClient({ cookies });
  const file = formData.get('file') as File;
  const jobId = formData.get('jobId') as string;

  try {
    // 1. Convert to Buffer for processing
    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);

    // 2. Upload to Supabase Storage (Audit Trail)
    const storagePath = `${jobId}/${Date.now()}-${file.name}`;
    const { data: storageData, error: storageError } = await supabase.storage
      .from('roofing-photos')
      .upload(storagePath, buffer, { contentType: file.type });

    if (storageError) throw storageError;

    // 3. Trigger Gemini Vision Analysis
    const analysis = await GeminiService.classifyRoofingImage(buffer, file.type);

    // 4. Retrieve Google Credentials from Supabase
    const { data: authData } = await supabase
      .from('integrations')
      .select('*')
      .eq('provider', 'google_drive')
      .single();

    const googleDrive = new GoogleWorkspaceService(
      authData.access_token,
      authData.refresh_token,
      authData.expiry
    );

    // 5. Organize in Google Drive
    // Logic: Find/Create Job Folder -> Find/Create Category Subfolder -> Upload
    const driveResult = await googleDrive.uploadToCategorizedFolder({
      jobId,
      category: analysis.category,
      fileName: file.name,
      fileBuffer: buffer,
      mimeType: file.type
    });

    // 6. Log to Database
    await supabase.from('photo_logs').insert({
      job_id: jobId,
      category: analysis.category,
      damage_detected: analysis.damage_detected,
      supabase_path: storagePath,
      drive_link: driveResult.webViewLink
    });

    return {
      success: true,
      fileName: file.name,
      analysis,
      driveUrl: driveResult.webViewLink
    };

  } catch (error) {
    console.error("Upload process failed:", error);
    return { success: false, error: "Processing failed" };
  }
}
```

#### B. Supabase Schema (SQL)
To support this module, the following tables are required:

```sql
-- Track integration tokens
CREATE TABLE integrations (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  provider TEXT NOT NULL, -- 'google_drive'
  access_token TEXT,
  refresh_token TEXT,
  expiry TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Audit log of all AI-categorized photos
CREATE TABLE photo_logs (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  job_id TEXT NOT NULL,
  category TEXT,
  damage_detected BOOLEAN,
  supabase_path TEXT,
  drive_link TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Enable RLS for Crew access
ALTER TABLE photo_logs ENABLE ROW LEVEL SECURITY;
```

---

### 4. Key Implementation Details

1.  **Memory Management:** I used `file.arrayBuffer()` and `Buffer.from()` to ensure the image data is handled efficiently within the Next.js Edge/Node runtime without creating massive memory leaks during high-volume uploads.
2.  **Resilience:** The system uploads to Supabase Storage *first*. If the AI or Google Drive API fails, the company still has the original photo safely stored in their private cloud, preventing data loss from the field.
