### 2. Implementation: Supabase Edge Function (`/supabase/functions/storm-lead-handler/index.ts`)

This function acts as the central orchestrator. It is optimized for the Deno runtime environment used by Supabase.

```typescript
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { GoogleGenerativeAI } from "https://esm.sh/@google/generative-ai@0.1.0";

// Constants for external services
const TWILIO_ACCOUNT_SID = Deno.env.get('TWILIO_ACCOUNT_SID');
const TWILIO_AUTH_TOKEN = Deno.env.get('TWILIO_AUTH_TOKEN');
const TWILIO_PHONE_NUMBER = Deno.env.get('TWILIO_PHONE_NUMBER');
const GOOGLE_SHEETS_ID = Deno.env.get('MASTER_SPREADSHEET_ID');

serve(async (req) => {
  const supabase = createClient(
    Deno.env.get('SUPABASE_URL') ?? '',
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
  );

  try {
    // 1. Parse Incoming Webhook Data (Facebook/Google format)
    const payload = await req.json();
    const leadData = {
      full_name: payload.full_name || payload.user_column_data?.[0]?.value,
      phone: payload.phone_number || payload.user_column_data?.[1]?.value,
      email: payload.email || payload.user_column_data?.[2]?.value,
      source: payload.source || 'Storm Webhook',
      raw_data: payload
    };

    // 2. Immediate Database Persistence
    const { data: leadRecord, error: dbError } = await supabase
      .from('leads')
      .insert([leadData])
      .select()
      .single();

    if (dbError) throw dbError;

    // 3. AI-Powered Response Generation
    // We use the 'Gemini-1.5-flash' for speed during high-volume storm events
    const genAI = new GoogleGenerativeAI(Deno.env.get('GEMINI_API_KEY')!);
    const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash" });

    const aiPrompt = `
      You are an emergency dispatcher for Apex Roofing. 
      A new lead just came in from ${leadData.source} named ${leadData.full_name}. 
      Draft a 140-character SMS that acknowledges the storm damage, 
      asks if they have an active leak, and mentions we are in their area.
    `;

    const aiResult = await model.generateContent(aiPrompt);
    const smsBody = aiResult.response.text();

    // 4. Dispatch SMS via Twilio
    const twilioRes = await fetch(
      `https://api.twilio.com/2010-04-01/Accounts/${TWILIO_ACCOUNT_SID}/Messages.json`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          Authorization: `Basic ${btoa(`${TWILIO_ACCOUNT_SID}:${TWILIO_AUTH_TOKEN}`)}`,
        },
        body: new URLSearchParams({
          To: leadData.phone,
          From: TWILIO_PHONE_NUMBER!,
          Body: smsBody,
        }),
      }
    );

    // 5. Sync to Google Sheets (Master Spreadsheet)
    await syncToGoogleSheets(leadData, smsBody);

    return new Response(JSON.stringify({ status: 'success', leadId: leadRecord.id }), {
      headers: { "Content-Type": "application/json" },
      status: 200,
    });

  } catch (error) {
    console.error("Critical Error in Lead Handler:", error.message);
    return new Response(JSON.stringify({ error: error.message }), { status: 500 });
  }
});

/**
 * Helper to push data to Google Sheets API
 */
async function syncToGoogleSheets(lead: any, initialResponse: string) {
  const GOOGLE_ACCESS_TOKEN = await getGoogleAccessToken(); // Method to refresh/fetch token from Supabase vault

  const range = "Leads!A:E";
  const valueInputOption = "USER_ENTERED";
  const url = `https://sheets.googleapis.com/v4/spreadsheets/${GOOGLE_SHEETS_ID}/values/${range}:append?valueInputOption=${valueInputOption}`;

  await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${GOOGLE_ACCESS_TOKEN}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      values: [[
        new Date().toISOString(),
        lead.full_name,
        lead.phone,
        lead.source,
        initialResponse
      ]],
    }),
  });
}
```

