### 2. The Reactivation Engine: `supabase/functions/aging-estimates-cron/index.ts`

This Edge Function acts as the orchestrator. It runs daily, fetches the "Estimates" sheet, filters for aging records, and triggers the AI generation.

```typescript
import { serve } from "https://deno.land/std@0.168.0/http/server.ts"
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { GoogleWorkspaceService } from '../../services/GoogleWorkspaceService.ts'
import { GeminiService } from '../../services/GeminiService.ts'

serve(async (req) => {
  try {
    const supabase = createClient(
      Deno.env.get('SUPABASE_URL')!,
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
    );

    // 1. Fetch Google Credentials for Apex Admin
    const { data: integration, error: authError } = await supabase
      .from('google_integrations')
      .select('*')
      .single();

    if (authError || !integration) {
      return new Response("Auth Integration not found", { status: 404 });
    }

    const googleService = new GoogleWorkspaceService(
      integration.access_token,
      integration.refresh_token,
      integration.expiry_date
    );

    // 2. Fetch Estimates from Google Sheets
    // Assumes Sheet Structure: [Date Sent, Name, Phone, Email, Damage Type, Amount, Status]
    const sheets = await googleService.getSpreadsheetValues(
      integration.spreadsheet_id, 
      'Estimates!A2:G100' // Adjust range as needed
    );

    const agingEstimates = filterAgingEstimates(sheets.values || []);
    const results = [];

    // 3. Process each aging estimate
    for (const estimate of agingEstimates) {
      const [dateSent, name, phone, email, damage, amount, status] = estimate;

      // Check if we've already followed up in the last 7 days to prevent spam
      const { data: existing } = await supabase
        .from('estimate_followups')
        .select('id')
        .eq('customer_phone', phone)
        .gt('sent_at', new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString())
        .maybeSingle();

      if (existing) continue;

      // 4. Generate AI Message using Gemini Service Layer
      const personalizedMessage = await GeminiService.generateEstimateFollowUp({
        name,
        damage,
        amount: parseFloat(amount.replace(/[^0-9.-]+/g, ""))
      });

      // 5. Dispatch via SMS (Example using Twilio/MessageBird integration)
      const dispatchResult = await sendSMS(phone, personalizedMessage);

      if (dispatchResult.success) {
        // 6. Log the success in Supabase
        await supabase.from('estimate_followups').insert({
          customer_email: email,
          customer_phone: phone,
          estimate_id: `${name}-${dateSent}`,
          message_content: personalizedMessage,
          channel: 'SMS'
        });

        results.push({ name, status: 'Followed-up' });
      }
    }

    return new Response(JSON.stringify({ processed: results.length, details: results }), {
      headers: { "Content-Type": "application/json" },
      status: 200,
    });

  } catch (err) {
    return new Response(JSON.stringify({ error: err.message }), { status: 500 });
  }
});

/**
 * Helper: Filters rows where Status is 'Pending' and Date is > 30 days old
 */
function filterAgingEstimates(rows: any[][]) {
  const thirtyDaysAgo = new Date();
  thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

  return rows.filter(row => {
    const dateSent = new Date(row[0]);
    const status = row[6]; // Column G: Status
    return status.toLowerCase() === 'pending' && dateSent < thirtyDaysAgo;
  });
}

