### 3. Specialized Components

#### C. Live AI Activity Feed (`LiveAIFeed.tsx`)
This component monitors the `photo_logs`, `dispatches`, and `lead_responses` tables to show the "Brain" of the company in action.

```tsx
// components/dashboard/LiveAIFeed.tsx
import { useEffect, useState } from 'react';
import { createClientComponentClient } from '@supabase/auth-helpers-nextjs';
import { Bot, Zap, MessageSquare, Camera, CheckCircle } from 'lucide-react';

export default function LiveAIFeed() {
  const [logs, setLogs] = useState<any[]>([]);
  const supabase = createClientComponentClient();

  useEffect(() => {
    // Initial fetch of recent AI activities
    const fetchLogs = async () => {
      const { data } = await supabase
        .from('ai_activity_logs') // Unified view or table for all AI actions
        .select('*')
        .order('created_at', { ascending: false })
        .limit(15);
      setLogs(data || []);
    };

    fetchLogs();

    // Subscribe to all AI-related tables
    const channel = supabase.channel('ai_updates')
      .on('postgres_changes', { event: 'INSERT', table: 'photo_logs' }, payload => {
        addLog({ type: 'photo', message: `Categorized: ${payload.new.category}`, jobId: payload.new.job_id });
      })
      .on('postgres_changes', { event: 'UPDATE', table: 'dispatches' }, payload => {
        addLog({ type: 'dispatch', message: `Crew Reply Parsed: ${payload.new.status}`, jobId: payload.new.job_id });
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, []);

  const addLog = (log: any) => setLogs(prev => [log, ...prev].slice(0, 15));

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 h-[calc(100vh-200px)] flex flex-col">
      <div className="p-4 border-b border-slate-100 flex items-center justify-between">
        <h3 className="font-bold text-slate-800 flex items-center gap-2">
          <Bot className="w-5 h-5 text-indigo-600" />
          AI Activity Stream
        </h3>
        <span className="flex h-2 w-2 rounded-full bg-green-500 animate-pulse"></span>
      </div>
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {logs.map((log, i) => (
          <div key={i} className="flex gap-3 text-sm animate-in fade-in slide-in-from-right-2">
            <div className={`mt-1 p-1.5 rounded-lg ${getIconBg(log.type)}`}>
              {getIcon(log.type)}
            </div>
            <div className="flex-1">
              <p className="text-slate-700 font-medium">{log.message}</p>
              <div className="flex justify-between items-center mt-1">
                <span className="text-xs text-slate-400 font-mono uppercase">{log.jobId}</span>
                <span className="text-[10px] text-slate-400">{new Date().toLocaleTimeString()}</span>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// Helper functions for UI styling
const getIcon = (type: string) => {
  switch(type) {
    case 'photo': return <Camera className="w-3.5 h-3.5 text-blue-600" />;
    case 'dispatch': return <Zap className="w-3.5 h-3.5 text-amber-600" />;
    case 'lead': return <MessageSquare className="w-3.5 h-3.5 text-green-600" />;
    default: return <Bot className="w-3.5 h-3.5 text-indigo-600" />;
  }
};

const getIconBg = (type: string) => {
  switch(type) {
    case 'photo': return 'bg-blue-50';
    case 'dispatch': return 'bg-amber-50';
    case 'lead': return 'bg-green-50';
    default: return 'bg-indigo-50';
  }
};
```

